query:
-- Fences
DELETE FROM projectTags WHERE projectId = (SELECT id FROM projects WHERE slug = 'fences');
INSERT INTO projectTags (projectId, tagId)
SELECT p.id, t.id FROM projects p CROSS JOIN tags t
WHERE p.slug = 'fences'
AND t.name IN ('1950s', 'Realistic Interior', 'Regional Theatre', '2023', 'Contemporary Drama', 'August Wilson');

-- Hamlet
DELETE FROM projectTags WHERE projectId = (SELECT id FROM projects WHERE slug = 'hamlet');
INSERT INTO projectTags (projectId, tagId)
SELECT p.id, t.id FROM projects p CROSS JOIN tags t
WHERE p.slug = 'hamlet'
AND t.name IN ('Shakespeare', 'Minimalist', 'Unit Set', 'Theatre Festival', '2023', 'Tragedy');

-- Merry Wives of Windsor
DELETE FROM projectTags WHERE projectId = (SELECT id FROM projects WHERE slug = 'merry-wives-of-windsor');
